import os
import sys
import time

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, ROOT)
from native import frametime as F  # noqa: E402

failed = []


def check(ok, what):
    print(("ok   " if ok else "FAIL ") + what)
    if not ok:
        failed.append(what)


F.clear()
for n, ms in (("interface", 4.0), ("polls", 6.0), ("views", 3.0), ("sim", 2.0)):
    F.add(n, ms)
F.add("VJ deck A", 1.0, "polls")
F.add("VJ deck B (MilkDrop)", 4.0, "polls")
F.add("the effect (engine)", 1.5, "sim")
F.add("library thumbnails", 20.0, "worker")
rows = F.rows()
names = [r[0] for r in rows]
check(names[:4] == ["polls", "VJ deck B (MilkDrop)", "VJ deck A", "sim"], f"a part, then what is in it, the biggest first ({names[:4]})")
check(names.index("views") < names.index("interface"), "the frame's parts in the frame's order")
check(rows[-1][0] == "library thumbnails" and rows[-1][2] == 1, "a worker's part after the frame's, as a row of its own")
check(all(d == 0 for n, _, d in rows if n in F.TOP), "the frame's parts at the top level")

F.add("polls", 16.0)
check(abs(dict((n, ms) for n, ms, _ in F.rows())["polls"] - (6.0 + 10.0 * F.SMOOTH)) < 1e-9, "smoothed, not the last measure")

with F.part("a block", "sim"):
    time.sleep(0.02)
got = dict((n, ms) for n, ms, _ in F.rows())
check(15.0 < got.get("a block", 0) < 200.0, f"a block timed ({got.get('a block')})")

F._avg["VJ deck A"][2] -= F.STALE_S + 1                     # not heard from for a while: a deck taken off air
check("VJ deck A" not in [r[0] for r in F.rows()], "a part not measured lately dropped")
F.add("VJ deck A", 9.0, "polls")
check(dict((n, ms) for n, ms, _ in F.rows())["VJ deck A"] == 9.0, "back after a while: from its new measure, not faded in")
check(len(F.rows(limit=3)) == 3, "at most the rows asked for")
print("FAILED:", failed) if failed else print("all ok")
sys.exit(1 if failed else 0)
